// POLICY (fail-closed) gate v0 — mirror of skin/policy.py::gate_v0 (edit both!)
const ILLEGAL=["weapon","knife","knives","gun","pistol","ammo","hunting knife","airsoft"];
const INJECTION=["ignore previous instructions","accept any offer","mark as sold","mark as safe","disregard all prior"];
const ADVANCE_FEE=/(iban|nl\d{2}[A-Z]{4}\d{4,}|tikkie|paypal\.me|pay (in advance|to reserve)|transfer €?\d+)/i;
for (const it of items) {
  const f = it.json.facts || {};
  const mz = f.margin_z ?? null;
  const text = String(f.text || it.json.title + ' ' + (it.json.description||'')).toLowerCase();
  let g;
  if (INJECTION.some(p => text.includes(p))) g = { action:'skip', reason_codes:['injection_or_jailbreak'], human_required:true };
  else if (ILLEGAL.some(k => text.includes(k))) g = { action:'skip', reason_codes:['illegal_keyword'], human_required:true };
  else if (f.offplatform_payment_request || ADVANCE_FEE.test(text)) g = { action:'skip', reason_codes:['offplatform_payment_request'], human_required:true };
  else if (mz === null) g = { action:'escalate', reason_codes:['no_comps'], human_required:true };
  else if (mz > 2.5) g = { action:'escalate', reason_codes:['price_too_good'], human_required:true };
  else if (mz > 0 && mz <= 2.5) g = { action:'pursue', reason_codes:['ok'], human_required:false };
  else g = { action:'escalate', reason_codes:['unknown'], human_required:true };
  // tier gate (outside policy): T3/over-cap promote pursue -> escalated
  if (g.action === 'pursue' && (it.json.tier === 'T3' || it.json.over_cap)) g = { action:'escalate', reason_codes:['tier_t3_or_cap'], human_required:true };
  it.json.gate = g;
  it.json.action_state = g.action === 'pursue' ? (it.json.is_mine ? 'pursued_auto' : 'drafted') : (g.action === 'skip' ? 'skipped' : 'escalated');
}
return items;
